import{_ as e,o as d,c as t,ap as c}from"./chunks/framework.BWFd5M2R.js";const h=JSON.parse('{"title":"行内元素和块级元素有什么区别？","description":"","frontmatter":{"password":"f364e34a3743eacf1767066da4b2699469e2f9fab3b63fdd112c672a3805497e"},"headers":[],"relativePath":"HTML/行内元素与块级元素.md","filePath":"HTML/行内元素与块级元素.md","lastUpdated":1773652575000}'),r={name:"HTML/行内元素与块级元素.md"};function n(a,o,s,i,g,l){return d(),t("div",null,[...o[0]||(o[0]=[c('<h1 id="行内元素和块级元素有什么区别" tabindex="-1">行内元素和块级元素有什么区别？ <a class="header-anchor" href="#行内元素和块级元素有什么区别" aria-label="Permalink to “行内元素和块级元素有什么区别？”">​</a></h1><p>面试里常说的「块级 / 行内」，本质上是<strong>浏览器默认样式表里，这类标签常用的 <code>display</code> 类型</strong>（多为 <code>block</code> 或 <code>inline</code>）。用 CSS 改掉 <code>display</code> 后，表现就跟着变——所以更准确的说法是：<strong>先记默认行为，再记可以用样式覆盖</strong>。</p><h2 id="一、默认表现对比-最常考" tabindex="-1">一、默认表现对比（最常考） <a class="header-anchor" href="#一、默认表现对比-最常考" aria-label="Permalink to “一、默认表现对比（最常考）”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>块级（典型 <code>display: block</code>）</th><th>行内（典型 <code>display: inline</code>，非替换元素）</th></tr></thead><tbody><tr><td>是否独占一行</td><td>是，前后会换行</td><td>否，在同一行内顺着排</td></tr><tr><td>宽度</td><td>默认撑满父级<strong>内容区</strong>宽度</td><td>由内容撑开</td></tr><tr><td><code>width</code> / <code>height</code></td><td>默认可生效</td><td>默认不参与块级那种宽高计算（见下）</td></tr><tr><td><code>margin</code>（上下）</td><td>参与布局，块级间可<strong>外边距折叠</strong></td><td><strong><code>margin-top</code> / <code>margin-bottom</code> 不生效</strong>（规范中计算为 0）</td></tr><tr><td><code>margin</code>（左右）</td><td>参与布局</td><td><strong><code>margin-left</code> / <code>margin-right</code> 生效</strong>，可拉开与两侧的距离</td></tr><tr><td><code>padding</code>（左右）</td><td>正常</td><td><strong><code>padding-left</code> / <code>padding-right</code> 生效</strong>，背景、边框随左右内边距扩展</td></tr><tr><td><code>padding</code>（上下）</td><td>正常</td><td><strong><code>padding-top</code> / <code>padding-bottom</code> 会画出来</strong>，但<strong>一般不增加本行行高</strong>，可能与上一行/下一行重叠</td></tr></tbody></table><blockquote><p>记忆口诀：<strong>行内左右 margin / padding 都能用；上下 margin 没用，上下 padding 有背景但未必撑开行高——要稳定控间距就改 <code>inline-block</code> / <code>block</code>。</strong></p></blockquote><p><strong>替换元素</strong>（如 <code>img</code>）在行内时，四边 <code>margin</code> 一般都可参与布局；宽高也可设，与纯文本类行内元素略有不同。</p><h2 id="二、常见标签举例" tabindex="-1">二、常见标签举例 <a class="header-anchor" href="#二、常见标签举例" aria-label="Permalink to “二、常见标签举例”">​</a></h2><p><strong>偏块级（默认块容器）</strong>：<code>div</code>、<code>p</code>、<code>h1</code>–<code>h6</code>、<code>section</code>、<code>article</code>、<code>header</code>、<code>footer</code>、<code>nav</code>、<code>ul</code> / <code>ol</code> / <code>li</code>、<code>form</code>、<code>table</code>、<code>hr</code>、<code>pre</code>、<code>blockquote</code> 等。</p><blockquote><p><strong><code>li</code></strong> 在默认 UA 样式里多为 <strong><code>display: list-item</code></strong>（生成列表项标记的块级框），<strong>不是</strong>单纯的 <code>block</code>，但占行、布局习惯上常和块级一起讨论。</p></blockquote><p><strong>偏行内（默认行内）</strong>：<code>span</code>、<code>a</code>、<code>strong</code>、<code>em</code>、<code>code</code>、<code>label</code>、<code>img</code>、<code>br</code> 等。</p><p><strong>容易混的</strong>：<code>img</code> 虽是行内置换元素，但可以设宽高（<strong>替换元素</strong>特性）；<code>input</code>、<code>button</code>、<code>textarea</code> 等表单控件在各浏览器里常见默认是 <strong><code>inline-block</code></strong>，既在一行里又能设宽高。</p><h2 id="三、和「行内块」inline-block-的关系" tabindex="-1">三、和「行内块」<code>inline-block</code> 的关系 <a class="header-anchor" href="#三、和「行内块」inline-block-的关系" aria-label="Permalink to “三、和「行内块」inline-block 的关系”">​</a></h2><p><code>display: inline-block</code> 对外像行内一样<strong>不换行</strong>，对内像块一样<strong>可设宽高、padding/margin 更直观</strong>。很多组件（按钮、徽标、头像）会刻意用行内块做排版。</p><h2 id="四、嵌套规则-面试常追问" tabindex="-1">四、嵌套规则（面试常追问） <a class="header-anchor" href="#四、嵌套规则-面试常追问" aria-label="Permalink to “四、嵌套规则（面试常追问）”">​</a></h2><p>HTML5 里用<strong>内容模型</strong>约束标签能不能包住谁，和「块 / 行内」说法交叉但不完全等同。最常踩坑的一条：</p><ul><li><strong><code>p</code> 里不能包块级元素</strong>（例如不能再包一层 <code>div</code>）。写了以后浏览器往往会<strong>自动补全结束标签</strong>，导致 DOM 和你写的不一样。</li></ul><p>语义上：<strong>块里可以包行内</strong>很常见；<strong>行内里直接塞块</strong>往往不合法或会被修正。</p><h2 id="五、小结-怎么答才显得「懂现代页面」" tabindex="-1">五、小结：怎么答才显得「懂现代页面」 <a class="header-anchor" href="#五、小结-怎么答才显得「懂现代页面」" aria-label="Permalink to “五、小结：怎么答才显得「懂现代页面」”">​</a></h2><ol><li><strong>块 / 行内</strong> 多指<strong>默认排版习惯</strong>，真正说了算的是 <strong><code>display</code></strong>。</li><li>块级：占行、默认可控宽度；行内：跟字走；<strong>左右 <code>margin</code> / <code>padding</code> 有效</strong>，<strong>上下 <code>margin</code> 无效</strong>，<strong>上下 <code>padding</code> 有绘制但常不撑行行高</strong>。</li><li><strong><code>img</code>、表单控件</strong>别死记成行内，要结合<strong>替换元素 / <code>inline-block</code></strong> 理解。</li><li>提一句 <strong><code>inline-block</code></strong> 和 <strong><code>p</code> 里不能嵌套块级</strong>；若问到 <code>li</code>，可答 <strong><code>list-item</code></strong> 默认表现接近块级。加分。</li></ol><blockquote><p>内容模型与标签分类：<a href="https://developer.mozilla.org/zh-CN/docs/Web/HTML/Content_categories" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/HTML/Content_categories</a></p></blockquote>',20)])])}const b=e(r,[["render",n]]);export{h as __pageData,b as default};
